local deferred = require "amf.script.sugar.deferred"
local ActivityModel = class("ActivityModel", AMFDataRef)

function ActivityModel:__installPlugs()
    -- 暂且不存
    -- self:installPlug(AMFDataPlugsType.STORAGE, {
    --     fileName = "user_local_activity",
    --     firstSyncInterval = 5
    -- }):as("db")
end

function ActivityModel:__declare()
    self[ActivityConst.ActivityConfigName] = {}
    self.rootUrl = ""
end

function ActivityModel:__init()
    self:setTempData("useRemoteConfig", false)
end

function ActivityModel:getRootUrl()
    return self.rootUrl
end

function ActivityModel:updateConfig(configName)
    local d = deferred.new()

    local saveValue = configName
    local tempFlag = "useRemoteConfig" .. configName

    -- 已经拉到过数据了，这次登录不再拉取（win32除外）
    if self:getTempData(tempFlag) and not (EnvUtil:isWindows() or EnvUtil:isUnityEditor() or EnvUtil:isMiniGameDev()) then
        d:resolve(self:getValue(saveValue))
        return d
    end
    local Loader 
    if EnvUtil:isUnityEditor() or ActivityConst.shouldUseLocalActivityConfig() then
        Loader = require("amf.middleware.activity.system.unity.ActivityConfigLoader")
    elseif EnvUtil:isDesktop() and not os.getenv("ACTIVITY_CFG_OL") then
        Loader = require("amf.middleware.activity.system.windows.ActivityConfigLoader")
    else
        Loader = require("amf.middleware.activity.loader.ActivityConfigLoader")
    end
        
    Loader:load(configName):next(function(res)
        ALog.log("activity", "load activity config success")
        self:setTempData(tempFlag, true)
        local data = self:parseActivityConfigData(res.data.activities)
        self:setValue(saveValue, data)
        self:setValue("rootUrl", res.data.rootUrl)
        d:resolve(data)
    end, function()
        ALog.log("activity", "load activity config fail")
        d:resolve(self:getValue(saveValue))
    end)
    return d
end

-- 过滤掉空的活动
function ActivityModel:parseActivityConfigData(configData)
    local newConfigData = {}
    for _, v in ipairs(configData or {}) do
        local isEmptyActivity = v.isEmptyActivity == "true" or v.isEmptyActivity == true
        if not isEmptyActivity then
            table.insert(newConfigData, v)
        end
    end
    return newConfigData
end

return ActivityModel
